#!/usr/bin/env bash
# Two-way directory sync between the host and an OpenShell sandbox.
#
#   bash sync.sh push <sandbox> <local-dir> <sandbox-dir>    host -> sandbox
#   bash sync.sh pull <sandbox> <local-dir> <sandbox-dir>    sandbox -> host
#   bash sync.sh diff <sandbox> <local-dir> <sandbox-dir>    dry-run, no changes
#
# Default transport is rsync over the sandbox SSH relay (alias generated by
# `openshell sandbox ssh-config`). SSH file transfers are limited by the
# supervisor's 4 MiB pending-stdin buffer: exceed it and the exec fails with
# exit code 74 ("process stdin buffer is full"), so rsync is throttled with
# --bwlimit. Raise SYNC_BWLIMIT until it breaks. SYNC_TAR=1 uses a tar pipe over
# the same SSH connection; SYNC_GATEWAY=1 routes the tar through
# `openshell sandbox upload` and `sandbox download`, which never touches SSH.
set -eu
cd "$(dirname "$0")"

action="${1:?usage: sync.sh push|pull|diff <sandbox> <local-dir> <sandbox-dir>}"
sandbox="${2:?sandbox name}"
local_dir="${3:?local directory}"
remote_dir="${4:?sandbox directory}"

ssh_host="openshell-${sandbox}.default"
if ! grep -qx "Host ${ssh_host}" "$HOME/.ssh/config" 2>/dev/null; then
  mkdir -p "$HOME/.ssh"
  openshell sandbox ssh-config "$sandbox" >> "$HOME/.ssh/config"
fi

excludes=(
  --exclude=node_modules --exclude=.venv --exclude=venv --exclude=__pycache__
  --exclude='*.pyc' --exclude=target --exclude=dist --exclude=.mypy_cache
)
bwlimit="--bwlimit=${SYNC_BWLIMIT:-2000}"

push_tar() {
  tar -czf - "${excludes[@]}" -C "$local_dir" . |
    ssh "$ssh_host" "mkdir -p '$remote_dir' && tar -xzf - -C '$remote_dir'"
}

pull_tar() {
  ssh "$ssh_host" "tar -czf - -C '$remote_dir' ." | tar -xzf - -C "$local_dir"
}

push_gateway() {
  local archive
  archive="$(mktemp -d)/$(basename "$local_dir").tar.gz"
  tar -czf "$archive" "${excludes[@]}" -C "$local_dir" .
  openshell sandbox upload "$sandbox" "$archive" "$remote_dir/.sync.tar.gz"
  openshell sandbox exec -n "$sandbox" -- \
    sh -c "tar -xzf '$remote_dir/.sync.tar.gz' -C '$remote_dir' && rm -f '$remote_dir/.sync.tar.gz'"
}

pull_gateway() {
  local staging
  staging="$(mktemp -d)"
  openshell sandbox exec -n "$sandbox" -- \
    sh -c "tar -czf /workspace/.sync.tar.gz -C '$remote_dir' ."
  openshell sandbox download "$sandbox" /workspace/.sync.tar.gz "$staging/.sync.tar.gz"
  tar -xzf "$staging/.sync.tar.gz" -C "$local_dir"
  openshell sandbox exec -n "$sandbox" -- rm -f /workspace/.sync.tar.gz
}

case "$action" in
  push)
    if [ "${SYNC_GATEWAY:-0}" = "1" ]; then push_gateway
    elif [ "${SYNC_TAR:-0}" = "1" ]; then push_tar
    else rsync -az --delete --timeout=60 "$bwlimit" "${excludes[@]}" "$local_dir/" "$ssh_host:$remote_dir/"
    fi
    ;;
  pull)
    if [ "${SYNC_GATEWAY:-0}" = "1" ]; then pull_gateway
    elif [ "${SYNC_TAR:-0}" = "1" ]; then pull_tar
    else rsync -az --delete --timeout=60 "$bwlimit" "${excludes[@]}" "$ssh_host:$remote_dir/" "$local_dir/"
    fi
    ;;
  diff)
    rsync -azn -i --delete --timeout=60 "$bwlimit" "${excludes[@]}" "$local_dir/" "$ssh_host:$remote_dir/"
    ;;
  *)
    echo "unknown action: $action" >&2
    exit 2
    ;;
esac
